package tz.tante.auth.manager.configs.feign;

import feign.RequestInterceptor;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import tz.tante.auth.manager.utilities.JwtUtils;

import java.time.Duration;

/**
 * Auth-manager is the token issuer, so service calls to rent-manager carry a short-lived
 * service token generated by JwtUtils, signed with the same key rent-manager trusts via the issuer JWKS.
 */
@Configuration
public class NotificationManagerFeignConfig
{
  private static final String SERVICE_SUBJECT = "auth-manager";
  private static final String NOTIFICATION_SCOPE = "notification.write";
  private static final Duration TOKEN_TTL = Duration.ofMinutes(5);

  private final JwtUtils jwtUtils;

  public NotificationManagerFeignConfig(JwtUtils jwtUtils)
  {
    this.jwtUtils = jwtUtils;
  }

  @Bean
  public RequestInterceptor rentManagerServiceTokenInterceptor()
  {
    return requestTemplate -> {
      String token = jwtUtils.generateServiceToken(SERVICE_SUBJECT, NOTIFICATION_SCOPE, TOKEN_TTL);
      requestTemplate.header("Authorization", "Bearer " + token);
    };
  }
}

